SELECT ?root ?rs ?yy (COUNT(DISTINCT ?c) AS ?n) WHERE {
 VALUES ?root {res:I01 res:I02 res:I05 res:I06 res:I07 res:I08 res:I14}
 ?a res:institution ?i ; res:work ?w .
 ?i res:parent* ?root .
 ?w res:workType ?t ; res:retracted false ; res:year ?y ; res:recordSource ?rs .
